var n=[{key:"directos",nombre:"M\xE9todos directos",principio:"Resuelven de una: triangularizan el sistema y despejan, sin iterar.",descripcion:"Transforman el sistema en uno triangular usando operaciones que no cambian la soluci\xF3n, y despu\xE9s despejan por sustituci\xF3n hacia atr\xE1s. El n\xFAmero de operaciones es fijo y se conoce de antemano: no hay criterio de parada porque no hay iteraci\xF3n. Son los que se usan en la pr\xE1ctica, y su l\xEDmite es el costo: O(n\xB3) para la eliminaci\xF3n."},{key:"iterativos",nombre:"M\xE9todos iterativos",principio:"Repiten un paso: van armando una aproximaci\xF3n de la soluci\xF3n.",descripcion:"Calculan nuevas aproximaciones a partir de un vector inicial. Cada barrida cuesta O(n\xB2) para una matriz densa y puede aprovechar los elementos no nulos de una matriz dispersa. La dominancia diagonal estricta por filas garantiza la convergencia de Jacobi y Gauss-Seidel. Se necesita comprobar el cambio, el residuo y el l\xEDmite de iteraciones; un buen condicionamiento por s\xED solo no garantiza convergencia."}],i=[{key:"gauss",nombre:"Eliminaci\xF3n Gaussiana",ruta:"gauss",familia:"directos",estado:"implementado",formula:"m\u1D62\u2096 = a\u1D62\u2096 / a\u2096\u2096   \xB7   R\u1D62 \u2190 R\u1D62 \u2212 m\u1D62\u2096 \xB7 R\u2096",idea:"Triangulariza el sistema con operaciones que no cambian la soluci\xF3n, y despu\xE9s despeja por sustituci\xF3n hacia atr\xE1s.",cuandoUsarlo:"Es el m\xE9todo por defecto: resuelve cualquier sistema en un n\xFAmero fijo de pasos y no necesita ninguna condici\xF3n previa. Con pivoteo parcial, adem\xE1s, es num\xE9ricamente estable.",iterativo:!1},{key:"lu",nombre:"Factorizaci\xF3n LU",ruta:"lu",familia:"directos",estado:"implementado",formula:"A = L \xB7 U   \xB7   L\xB7y = b   \u2192   U\xB7x = y",idea:"La eliminaci\xF3n gaussiana, pero guardada: la triangularizaci\xF3n se hace una sola vez y cada sistema nuevo se resuelve con dos sustituciones.",cuandoUsarlo:"Cuando el mismo sistema (o la misma matriz A) se va a resolver muchas veces con distintos lados derechos. Es la base de los resolutores reales.",iterativo:!1},{key:"jacobi",nombre:"Jacobi",ruta:"jacobi",familia:"iterativos",estado:"implementado",formula:"x\u1D62\u207D\u1D4F\u207A\xB9\u207E = (b\u1D62 \u2212 \u03A3\u2C7C\u2260\u1D62 a\u1D62\u2C7C x\u2C7C\u207D\u1D4F\u207E) / a\u1D62\u1D62",idea:"Despeja cada inc\xF3gnita usando el valor VIEJO de las dem\xE1s, todas a la vez.",cuandoUsarlo:"Permite calcular las componentes de una barrida de forma independiente. La dominancia diagonal estricta garantiza convergencia; sin esa garant\xEDa hay que estudiar el sistema y observar el residuo.",iterativo:!0},{key:"gaussSeidel",nombre:"Gauss-Seidel",ruta:"gauss-seidel",familia:"iterativos",estado:"implementado",formula:"x\u1D62\u207D\u1D4F\u207A\xB9\u207E = (b\u1D62 \u2212 \u03A3\u2C7C<\u1D62 a\u1D62\u2C7C x\u2C7C\u207D\u1D4F\u207A\xB9\u207E \u2212 \u03A3\u2C7C>\u1D62 a\u1D62\u2C7C x\u2C7C\u207D\u1D4F\u207E) / a\u1D62\u1D62",idea:"Igual que Jacobi, pero usa el valor NUEVO de las inc\xF3gnitas que ya resolvi\xF3.",cuandoUsarlo:"Reutiliza las actualizaciones dentro de la misma barrida y puede necesitar menos iteraciones. Converge para matrices estrictamente diagonalmente dominantes o sim\xE9tricas definidas positivas.",iterativo:!0}],r=i.reduce((a,e)=>(a[e.key]=e,a),{});function d(a){return i.filter(e=>e.familia===a)}function l(a){let e=r[a],o=n.find(t=>t.key===e.familia);if(!o)throw new Error(`Familia del M\xF3dulo 2 no registrada: "${e.familia}".`);return o}function s(a){return`/modulo2/tipos/${a}`}function u(a){return`${s(a.familia)}/${a.ruta}/teoria`}export{n as a,i as b,d as c,l as d,s as e,u as f};
